from functools import lru_cache
R=C=5
start=sum(1<<(r*C+c) for r,c in [(1,3),(1,4),(2,4),(3,3),(3,4),(4,3)])
dirs=[(-1,0),(1,0),(0,-1),(0,1)]
@lru_cache(None)
def paths(s):
    if s.bit_count()==1:return [[]]
    out=[]
    for r in range(R):
      for c in range(C):
       b=r*C+c
       if not(s>>b&1):continue
       for dr,dc in dirs:
        r1,c1=r+dr,c+dc;r2,c2=r+2*dr,c+2*dc
        if 0<=r2<R and 0<=c2<C:
         b1=r1*C+c1;b2=r2*C+c2
         if s>>b1&1 and not(s>>b2&1):
          ns=s^(1<<b)^(1<<b1)^(1<<b2)
          for p in paths(ns):out.append([((r,c),(r2,c2))]+p)
    return out
ps=paths(start)
len(ps),ps[:3]

seen={}
def dfs(s,path=[]):
    if s in seen:return
    seen[s]=path
    for r in range(R):
      for c in range(C):
       b=r*C+c
       if not(s>>b&1):continue
       for dr,dc in dirs:
        r1,c1=r+dr,c+dc;r2,c2=r+2*dr,c+2*dc
        if 0<=r2<R and 0<=c2<C:
         b1=r1*C+c1;b2=r2*C+c2
         if s>>b1&1 and not(s>>b2&1):
          dfs(s^(1<<b)^(1<<b1)^(1<<b2),path+[((r,c),(r2,c2))])
dfs(start)
min(s.bit_count() for s in seen),[(s.bit_count(),p) for s,p in seen.items() if s.bit_count()==min(t.bit_count() for t in seen)][:2]

